import java.util.*;
import java.io.*;

public class Main {
    static final int T = 99;
    static final int C = 15;
    static final long INF = 0x3f3f3f3fL;
    static final int N = 50 * T + 2;
    static final int M = 2 * N * C + N + 7;

    static int[] par = new int[N];
    static int[] first = new int[N];
    static int[] nxt = new int[2 * M];
    static int[] ep = new int[2 * M];
    static long[] flo = new long[2 * M];
    static long[] cap = new long[2 * M];
    static long[] cost = new long[2 * M];
    static int m;

    static int[] q = new int[N];
    static int[] inq = new int[N];
    static boolean[] vis = new boolean[N];
    static long[] pot = new long[N];
    static long[] dist = new long[N];

    static void init() {
        m = 0;
        Arrays.fill(first, -1);
        Arrays.fill(flo, 0);
    }

    static void add_edge(int a, int b, long c, long p) {
        nxt[m] = first[ep[m] = a];
        first[ep[m]] = m;
        cap[m] = c;
        cost[m] = p;
        m++;
        nxt[m] = first[ep[m] = b];
        first[ep[m]] = m;
        cap[m] = 0;
        cost[m] = -p;
        m++;
    }

    static void mcf_pot_init(int n) {
        Arrays.fill(pot, 0);
        for (int k = 1; k < n; k++) {
            for (int e = 0; e < m; e++) {
                if (cap[e] != 0) {
                    int u = ep[e];
                    int v = ep[e ^ 1];
                    if (pot[v] > pot[u] + cost[e]) {
                        pot[v] = pot[u] + cost[e];
                    }
                }
            }
        }
    }

    static long mcf_update(int s, int t, long[] price, int n) {
        Arrays.fill(vis, false);
        Arrays.fill(dist, INF);
        Arrays.fill(inq, -1);
        dist[s] = 0;
        int qs = 0;
        q[qs++] = s;
        inq[s] = 0;
        while (qs > 0) {
            int u = q[0];
            int[] tempQ = new int[qs - 1];
            System.arraycopy(q, 1, tempQ, 0, qs - 1);
            System.arraycopy(tempQ, 0, q, 0, qs - 1);
            qs--;
            inq[u] = -1;
            for (int i = 0; i < qs; i++) {
                int j = 2 * i + 1;
                int e;
                if (j + 1 < qs && dist[q[j + 1]] < dist[q[j]]) {
                    j++;
                }
                if (dist[q[j]] >= dist[q[i]]) continue;
                int tIdx = q[i];
                q[i] = q[j];
                q[j] = tIdx;
            }
            if (vis[u]) continue;
            vis[u] = true;
            for (int e = first[u]; e != -1; e = nxt[e]) {
                int v = ep[e ^ 1];
                if (flo[e] < cap[e] && dist[v] > dist[u] + pot[u] - pot[v] + cost[e]) {
                    dist[v] = dist[u] + pot[u] - pot[v] + cost[e];
                    par[v] = e;
                    if (inq[v] < 0) {
                        inq[q[qs] = v] = qs;
                        qs++;
                    }
                    for (int i = inq[v], j = (i - 1) / 2; i > 0 && dist[q[i]] < dist[q[j]]; i = j, j = (i - 1) / 2) {
                        int tmp = q[i];
                        q[i] = q[j];
                        q[j] = tmp;
                    }
                }
            }
        }
        if (dist[t] >= INF) return 0;
        long df = INF;
        for (int e, i = t; i != s; i = ep[e]) {
            e = par[i];
            if (cap[e] - flo[e] < df) df = cap[e] - flo[e];
        }
        for (int e, i = t; i != s; i = ep[e]) {
            e = par[i];
            flo[e] += df;
            flo[e ^ 1] -= df;
            price[0] += df * cost[e];
        }
        for (int i = 0; i < n; i++) {
            if (dist[i] + pot[i] < INF) {
                pot[i] = Math.min(INF, dist[i] + pot[i]);
            }
        }
        return df;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int source = 0;
        int sink = n * T + 1;

        init();

        for (int i = 0; i < k; i++) {
            int a = Integer.parseInt(br.readLine());
            add_edge(source, a, 1, 0);
        }

        for (int t = 0; t < T; t++) {
            add_edge(1 + t * n, sink, INF, 0);
            if (t > 0) {
                for (int i = 1; i <= n; i++) {
                    add_edge(i + (t - 1) * n, i + t * n, INF, c);
                }
            }
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            for (int j = 0; j < C; j++) {
                int costVal = (j + 1) * (j + 1) - j * j;
                for (int t = 1; t < T; t++) {
                    add_edge(a + (t - 1) * n, b + t * n, 1, costVal * d + c);
                    add_edge(b + (t - 1) * n, a + t * n, 1, costVal * d + c);
                }
            }
        }

        mcf_pot_init(N);
        long price = 0;
        long flow = 0;
        long[] priceArr = new long[1];
        while (true) {
            long df = mcf_update(source, sink, priceArr, N);
            if (df == 0) break;
            flow += df;
        }
        if (flow != k) {
            throw new AssertionError("Flow does not match k");
        }
        System.out.println(priceArr[0]);
    }
}
